// Author: MiYu. Live source invisibility checks hostile targeting, detector invalidation, native queries and shared vision.
#include "session.h"
#include "setup.h"
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_visibility_tests <data-root> <fixture> [spell|passive|potion]");std::wstring mode=argc>3?argv[3]:L"spell";if(mode!=L"spell" && mode!=L"passive" && mode!=L"potion")throw std::runtime_error("Unknown visibility check mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());setup.control(1,SlotControl::ComputerNormal);session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto& ai=*session.ais()[1]->runtime;auto call=[](jass::Runtime& runtime,const char* name,std::initializer_list<jass::Value> args){return runtime.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto caster=vm.global("caster"),target=vm.global("target"),enemy=vm.global("enemy_unit"),detector=vm.global("detector");auto p0=call(vm,"Player",{vm.integer(0)}),p1=call(vm,"Player",{vm.integer(1)});auto type=[](const char* code){return int(ObjectData::code(code));};auto point=[&](int value){return vm.real(jass::Real::fromInteger(value));};
        require(!(session.config().players[0].alliances[1]&1) && !(session.config().players[1].alliances[0]&1),"Visibility fixture requires hostile players");
        require(call(vm,"IsUnitVisible",{target,p1}).bits && !call(vm,"IsUnitInvisible",{target,p1}).bits && !call(vm,"IsUnitDetected",{target,p1}).bits,"Ordinary sight was confused with detection");
        if(mode==L"passive"){
            require(call(vm,"UnitAddAbility",{target,vm.integer(type("Apiv"))}).bits,"Permanent invisibility source ability was not added");require(!session.unitInvisible(target.bits),"Permanent invisibility skipped source fade");session.advance(2.125);require(session.unitInvisible(target.bits) && !session.unitVisibleTo(target.bits,1),"Permanent invisibility did not fade in");require(call(vm,"IssueTargetOrder",{target,vm.string("attack"),enemy}).bits,"Permanent invisible unit could not explicitly attack");session.advance(.0625);require(!session.unitInvisible(target.bits),"Attack windup did not break permanent invisibility");call(vm,"IssueImmediateOrder",{target,vm.string("stop")});session.advance(2.125);require(session.unitInvisible(target.bits),"Permanent invisibility did not recover after source delay");std::cout<<"PASS permanent_invisibility_attack_and_recovery\n";
        }else{
            if(mode==L"potion"){auto item=call(vm,"UnitAddItemById",{target,vm.integer(type("pinv"))});require(item.bits && call(vm,"UnitUseItem",{target,item}).bits,"Original invisibility potion failed to consume");}else require(call(vm,"IssueTargetOrder",{caster,vm.string("invisibility"),target}).bits,"Original invisibility order was rejected");session.advance(1);require(session.unitInvisible(target.bits) && call(vm,"GetUnitAbilityLevel",{target,vm.integer(type("Binv"))}).bits && call(vm,"IsUnitInvisible",{target,p1}).bits && !call(vm,"IsUnitVisible",{target,p1}).bits && !call(vm,"IsUnitInvisible",{target,p0}).bits && call(vm,"IsUnitVisible",{target,p0}).bits && call(ai,"UnitInvis",{ai.handle("unit",target.bits)}).bits,"Invisible state/native/player/AI queries disagree");require(!call(vm,"IssueTargetOrder",{enemy,vm.string("attack"),target}).bits,"Enemy directly attacked an undetected invisible unit");
            call(vm,"SetUnitPosition",{detector,point(192),point(0)});require(call(vm,"IsUnitDetected",{target,p1}).bits && call(vm,"IsUnitVisible",{target,p1}).bits && !call(vm,"IsUnitInvisible",{target,p1}).bits && !call(ai,"UnitInvis",{ai.handle("unit",target.bits)}).bits,"Source true sight did not reveal invisibility to its player");call(vm,"SetUnitPosition",{detector,point(2048),point(0)});require(!call(vm,"IsUnitDetected",{target,p1}).bits && call(vm,"IsUnitInvisible",{target,p1}).bits,"Detector movement did not invalidate the same-tick cache");
            call(vm,"UnitShareVision",{target,p1,vm.boolean(true)});require(session.unitVisibleTo(target.bits,1) && !session.unitInvisibleTo(target.bits,1),"Explicit unit shared vision did not reveal its own unit");call(vm,"UnitShareVision",{target,p1,vm.boolean(false)});require(!session.unitVisibleTo(target.bits,1),"Revoked unit vision left invisible unit exposed");require(call(vm,"IssuePointOrder",{target,vm.string("move"),point(160),point(0)}).bits,"Invisible unit could not move");session.advance(.125);require(session.unitInvisible(target.bits),"Movement broke ordinary invisibility");require(call(vm,"IssueTargetOrder",{target,vm.string("attack"),enemy}).bits,"Invisible unit could not attack a visible enemy");session.advance(.0625);require(!session.unitInvisible(target.bits) && session.unitVisibleTo(target.bits,1),"Actual attack windup did not reveal the attacker");std::cout<<"PASS invisibility_native_targeting_detection_movement_and_attack\n";
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
